import ctypes, os

from typing import Optional, AnyStr
from .enums import *
from ._binaryninjacore_loader import check_core_abi, load_core

# Load core module
core, _base_path = load_core()
BN_EXPECTED_CORE_ABI_VERSION = 186

check_core_abi(core, BN_EXPECTED_CORE_ABI_VERSION)


def cstr(var: Optional[AnyStr]) -> Optional[bytes]:
	if var is None:
		return None
	if isinstance(var, bytes):
		return var
	return var.encode("utf-8")


def pyNativeStr(arg: Optional[AnyStr]) -> Optional[str]:
	if arg is None or isinstance(arg, str):
		return arg
	else:
		try:
			return arg.decode('utf8')
		except UnicodeDecodeError:
			return arg.decode('charmap')


def free_string(value:ctypes.c_char_p) -> None:
	BNFreeString(ctypes.cast(value, ctypes.POINTER(ctypes.c_byte)))

