_BNAllocStringWithLength.restype = ctypes.POINTER(ctypes.c_byte)
_BNAllocStringWithLength.argtypes = [
		ctypes.c_char_p,
		ctypes.c_ulonglong,
	]


# noinspection PyPep8Naming
def BNAllocStringWithLength(
		contents: 'Optional[str]', 
		len: 'int'
		) -> Optional['Optional[str]']:
	result = _BNAllocStringWithLength(cstr(contents), len)
	casted = ctypes.cast(result, ctypes.c_char_p).value
	if casted is None:
		return None
	string = str(pyNativeStr(casted))
	BNFreeString(result)
	return string


