# _BNRemoteRequestAuthenticationToken

_BNRemoteRequestAuthenticationToken = core.BNRemoteRequestAuthenticationToken
_BNRemoteRequestAuthenticationToken.restype = ctypes.POINTER(ctypes.c_byte)
_BNRemoteRequestAuthenticationToken.argtypes = [
		ctypes.POINTER(BNRemote),
		ctypes.c_char_p,
		ctypes.c_char_p,
	]


# noinspection PyPep8Naming
def BNRemoteRequestAuthenticationToken(
		remote: 'ctypes._Pointer[BNRemote]', 
		username: 'Optional[str]', 
		password: 'Optional[str]'
		) -> Optional['Optional[str]']:
	result = _BNRemoteRequestAuthenticationToken(remote, cstr(username), cstr(password))
	casted = ctypes.cast(result, ctypes.c_char_p).value
	if casted is None:
		return None
	string = str(pyNativeStr(casted))
	BNFreeString(result)
	return string


